      "statement": "The harness sets both CRC actions to PNG_CRC_QUIET_USE and conditionally enables PNG_IGNORE_ADLER32 when that macro exists.",
      "evidence": [
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 121, "end_line": 125, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "png_read_info accepts a stream whose signature bytes were already consumed through png_set_sig_bytes, then dispatches pre-IDAT chunks, including iCCP, zTXt and iTXt when their respective read support macros are enabled.",
      "evidence": [
        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 82, "end_line": 104, "role": "primary", "dependency_reason": ""},
