      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "png_read_end also dispatches trailing iCCP, zTXt and iTXt chunks under their read support macros; the target passes a non-null end_info_ptr.",
      "evidence": [
        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 760, "end_line": 766, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 895, "end_line": 929, "role": "primary", "dependency_reason": ""},
