        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 152, "end_line": 167, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The source row reader consumes IDAT through png_read_IDAT_data and the harness invokes that row reader for each pass and row. This is an existing route for IDAT processing.",
