        {"unit_id": "u-cc1e0b2b98d159b17936", "start_line": 538, "end_line": 543, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-e9cdca141412a92154b2", "start_line": 169, "end_line": 177, "role": "dependency", "dependency_reason": "The target invokes png_read_row in its pass and row loops."}
      ],
